package mz.bam.seeky.android;
import android.content.*;import android.view.*;import android.widget.*;
final class FlashSettings {
 static final String OPEN="open_flash_settings";
 static int opacity(Context c){return Math.max(20,Math.min(100,c.getSharedPreferences("seeky",0).getInt("flash_opacity",100)));}
 static int delay(Context c){return Math.max(3,Math.min(30,c.getSharedPreferences("seeky",0).getInt("flash_idle_seconds",10)));}
 /** Recolha automática para a margem: ligada por omissão (pedido 5.19.0). */
 static boolean autoHide(Context c){return c.getSharedPreferences("seeky",0).getBoolean("flash_auto_hide",true);}
 static void open(Context c){c.startActivity(new Intent(c,MainActivity.class).putExtra(OPEN,true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));}
 static void slider(MainActivity a,LinearLayout fields,String title,int min,int max,int value,java.util.function.IntConsumer change){TextView label=a.label(title+value,13,a.text);fields.addView(label);SeekBar bar=new SeekBar(a);bar.setMax(max-min);bar.setProgress(value-min);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int n,boolean user){label.setText(title+(n+min));if(user)change.accept(n+min);}});fields.addView(bar,new LinearLayout.LayoutParams(-1,a.dp(44)));}
 static void show(MainActivity a){LinearLayout fields=a.column();fields.addView(new SizeControl(a,"Ícones","icon_size",n->{a.iconSize=n;a.render();}));fields.addView(new SizeControl(a,"Botão Flash","flash_button_size",n->{}));fields.addView(a.label("O botão pode ficar menor; a zona de toque mantém-se acessível.",12,a.muted));slider(a,fields,"Transparência (%) · ",0,80,100-opacity(a),n->a.prefs.edit().putInt("flash_opacity",100-n).apply());Switch auto=new Switch(a);auto.setText("Recolher quando não estiver em uso");auto.setTextColor(a.text);auto.setChecked(autoHide(a));auto.setOnCheckedChangeListener((v,on)->a.prefs.edit().putBoolean("flash_auto_hide",on).apply());fields.addView(auto);slider(a,fields,"Tempo até recolher (segundos) · ",3,30,delay(a),n->a.prefs.edit().putInt("flash_idle_seconds",n).apply());fields.addView(a.label("Posição de recolha",12,a.muted));ChoiceSpinner position=new ChoiceSpinner(a);position.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,new String[]{"Margem mais próxima","Canto superior esquerdo","Canto superior direito","Canto inferior esquerdo","Canto inferior direito"}));int selected=Math.max(0,Math.min(4,a.prefs.getInt("flash_corner",0)));position.setSelection(selected);position.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int at,long id){if(at!=a.prefs.getInt("flash_corner",0))a.prefs.edit().putInt("flash_corner",at).apply();}});fields.addView(position);fields.addView(a.label("Quando recolhido, metade do botão fica visível na margem com a lupa à vista. Toque para abrir a pesquisa ou arraste para mover.",12,a.muted));a.dialog().setTitle("Ícones e botão Flash").setView(fields).setPositiveButton("Fechar",null).setNeutralButton("Restaurar Flash",(d,w)->a.prefs.edit().remove("flash_button_size").remove("flash_opacity").remove("flash_auto_hide").remove("flash_idle_seconds").remove("flash_corner").apply()).show();}
 private FlashSettings(){}
}
